    "context.logSources.0.description": "HTTP requests and responses. Check the source, requested URL, status, response size, and request_id.",
    "context.logSources.1.description": "Text audit records of application decisions and business events. Correlate them with HTTP results.",
    "context.logSources.2.description": "Application audit records in JSON Lines format. Each line is one event, representing the same events as the corresponding audit.log.",
    "context.logSources.3.description": "SSH authentication, sessions, and sudo records in traditional syslog format. Interpret the year as 2026 and times as UTC; correlate source, account, session, and privilege use.",
    "context.logSources.4.description": "Separately collected access records from the target Web server. Compare period, request IDs, and line counts against the target host’s access.log.",
